      chapters: { problem: "The problem", prompts: "Two prompts", open: "What open does", blocked: "What blocked does", moment: "The bind moment", models: "Other models", sae: "Construction × SAE", ledger: "Ledger" }, pos: "row", posSite: "position", posTok: "token", posRel: "distance",
